/**
 * Event Bus - In-memory pub/sub message broker
 * Enables decoupled communication between services
 */

type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event handler for ${event}:`, error);
        }
      });
    }
  }

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

export const eventBus = new EventBus();

/**
 * User Service - Manages user CRUD operations
 */

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserRequest {
  name: string;
  email: string;
}

export interface UpdateUserRequest {
  name?: string;
  email?: string;
}

export class UserService {
  private userStore: Map<string, User> = new Map();

  /**
   * Create a new user
   */
  create(req: CreateUserRequest): User {
    const user: User = {
      id: randomUUID(),
      name: req.name,
      email: req.email,
    };
    this.userStore.set(user.id, user);
    return user;
  }

  /**
   * Get a user by ID
   */
  getById(id: string): User | undefined {
    return this.userStore.get(id);
  }

  /**
   * Get all users
   */
  getAll(): User[] {
    return Array.from(this.userStore.values());
  }

  /**
   * Update a user
   */
  update(id: string, req: UpdateUserRequest): User | undefined {
    const user = this.userStore.get(id);
    if (!user) {
      return undefined;
    }
    if (req.name !== undefined) {
      user.name = req.name;
    }
    if (req.email !== undefined) {
      user.email = req.email;
    }
    return user;
  }

  /**
   * Delete a user
   */
  delete(id: string): boolean {
    return this.userStore.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service - Manages projects and membership
 */

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectRequest {
  name: string;
  description: string;
}

export interface UpdateProjectRequest {
  name?: string;
  description?: string;
}

export interface AddMemberRequest {
  userId: string;
}

export interface RemoveMemberRequest {
  userId: string;
}

export class ProjectService {
  private projectStore: Map<string, Project> = new Map();

  /**
   * Create a new project
   */
  create(req: CreateProjectRequest): Project {
    const project: Project = {
      id: randomUUID(),
      name: req.name,
      description: req.description,
      memberIds: [],
    };
    this.projectStore.set(project.id, project);
    return project;
  }

  /**
   * Get a project by ID
   */
  getById(id: string): Project | undefined {
    return this.projectStore.get(id);
  }

  /**
   * Get all projects
   */
  getAll(): Project[] {
    return Array.from(this.projectStore.values());
  }

  /**
   * Update a project
   */
  update(id: string, req: UpdateProjectRequest): Project | undefined {
    const project = this.projectStore.get(id);
    if (!project) {
      return undefined;
    }
    if (req.name !== undefined) {
      project.name = req.name;
    }
    if (req.description !== undefined) {
      project.description = req.description;
    }
    return project;
  }

  /**
   * Delete a project
   */
  delete(id: string): boolean {
    return this.projectStore.delete(id);
  }

  /**
   * Add a member to a project
   */
  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.projectStore.get(projectId);
    if (!project) {
      return undefined;
    }
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  /**
   * Remove a member from a project
   */
  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.projectStore.get(projectId);
    if (!project) {
      return undefined;
    }
    project.memberIds = project.memberIds.filter(id => id !== userId);
    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service - Manages tasks with status transitions
 * Publishes: task.assigned, task.statusChanged
 */

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskRequest {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskRequest {
  title?: string;
  description?: string;
}

export interface AssignTaskRequest {
  assigneeId: string | null;
}

export interface ChangeStatusRequest {
  status: TaskStatus;
}

export class TaskService {
  private taskStore: Map<string, Task> = new Map();

  /**
   * Create a new task
   */
  create(req: CreateTaskRequest): Task {
    const task: Task = {
      id: randomUUID(),
      title: req.title,
      description: req.description,
      status: 'todo',
      assigneeId: null,
      projectId: req.projectId,
    };
    this.taskStore.set(task.id, task);
    return task;
  }

  /**
   * Get a task by ID
   */
  getById(id: string): Task | undefined {
    return this.taskStore.get(id);
  }

  /**
   * Get all tasks for a project
   */
  getByProject(projectId: string): Task[] {
    return Array.from(this.taskStore.values()).filter(
      task => task.projectId === projectId
    );
  }

  /**
   * Update a task (title/description only)
   */
  update(id: string, req: UpdateTaskRequest): Task | undefined {
    const task = this.taskStore.get(id);
    if (!task) {
      return undefined;
    }
    if (req.title !== undefined) {
      task.title = req.title;
    }
    if (req.description !== undefined) {
      task.description = req.description;
    }
    return task;
  }

  /**
   * Delete a task
   */
  delete(id: string): boolean {
    return this.taskStore.delete(id);
  }

  /**
   * Assign a task to a user
   */
  assign(id: string, req: AssignTaskRequest): Task | undefined {
    const task = this.taskStore.get(id);
    if (!task) {
      return undefined;
    }
    const oldAssigneeId = task.assigneeId;
    task.assigneeId = req.assigneeId;

    // Publish task.assigned event if assigning to someone
    if (req.assigneeId) {
      eventBus.publish('task.assigned', {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId: req.assigneeId,
      });
    }

    return task;
  }

  /**
   * Change task status with forward-only validation
   * Allowed transitions: todo -> in-progress -> done
   */
  changeStatus(id: string, req: ChangeStatusRequest): Task | undefined {
    const task = this.taskStore.get(id);
    if (!task) {
      return undefined;
    }

    // Validate forward-only transition
    const statusOrder: Record<TaskStatus, number> = {
      'todo': 0,
      'in-progress': 1,
      'done': 2,
    };

    if (statusOrder[req.status] <= statusOrder[task.status]) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${req.status}. Only forward transitions allowed.`
      );
    }

    const oldStatus = task.status;
    task.status = req.status;

    // Publish task.statusChanged event if task has an assignee
    if (task.assigneeId) {
      eventBus.publish('task.statusChanged', {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId: task.assigneeId,
        oldStatus,
        newStatus: req.status,
      });
    }

    return task;
  }
}

export const taskService = new TaskService();

/**
 * Comment Service - Manages comments on tasks
 * Publishes: comment.added
 */

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export interface CreateCommentRequest {
  taskId: string;
  authorId: string;
  body: string;
}

export class CommentService {
  private commentStore: Map<string, Comment> = new Map();

  /**
   * Create a new comment
   */
  create(req: CreateCommentRequest, taskTitle: string): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId: req.taskId,
      authorId: req.authorId,
      body: req.body,
      createdAt: new Date().toISOString(),
    };
    this.commentStore.set(comment.id, comment);

    // Publish comment.added event
    eventBus.publish('comment.added', {
      commentId: comment.id,
      taskId: req.taskId,
      taskTitle: taskTitle,
      authorId: req.authorId,
      authorName: req.authorId, // Note: should be author name, but we'll pass the ID here
    });

    return comment;
  }

  /**
   * Get a comment by ID
   */
  getById(id: string): Comment | undefined {
    return this.commentStore.get(id);
  }

  /**
   * Get all comments for a task
   */
  getByTask(taskId: string): Comment[] {
    return Array.from(this.commentStore.values()).filter(
      comment => comment.taskId === taskId
    );
  }

  /**
   * Delete a comment
   */
  delete(id: string): boolean {
    return this.commentStore.delete(id);
  }
}

